// The teacher's school-domain address — persons.classroom_email — has ONE reader.
//
// The address is GENERATED by teacher-account.ts (chooseAddress + createGoogleAccount)
// and written once; it is READ here and nowhere else. Files reading the column raw each decided for themselves what
// "missing" meant (null; ''; whitespace) and how two addresses compare (as stored; trimmed; trimmed and lowered).
// Reading and creating are separate: one get, one rule.
//
// The rule: trimmed and lowercased, null when absent or blank — the form the unique index
// persons_tenant_classroom_email_unique compares in, and the form Google answers in.

import { db } from './db'
import { persons } from '../tables'
import { and, eq, isNotNull, sql } from 'drizzle-orm'
import { workspaceDomain } from './role-mailbox'

// THE DOMAIN IS THE TENANT'S: teacher accounts are minted in the tenant's directory domain, the tenant
// value `workspace-domain` (read with workspaceDomain(tenantId)), and every rule below takes it as an argument.

/** Is this a teacher-domain address? Children of a teacher are not allowed to
 *  use the teacher-domain address — a student never stands on one, own or borrowed. */
export function isTeacherDomainAddress(address: string, domain: string): boolean {
  return address.trim().toLowerCase().endsWith(`@${domain.trim().toLowerCase()}`)
}

export type HasClassroomEmail = { email: string | null | undefined; classroomEmail: string | null | undefined }

/**
 * The teacher's school-domain address, or null when they have none.
 *
 * A PRIMARY address in the teacher domain IS the classroom address: if the primary email
 * address is in the teacher domain, the other column is irrelevant. Otherwise the
 * generated column.
 */
export function teacherClassroomAddress(p: HasClassroomEmail, domain: string): string | null {
  const primary = p.email?.trim().toLowerCase()
  if (primary && isTeacherDomainAddress(primary, domain)) return primary
  const a = p.classroomEmail?.trim().toLowerCase()
  return a ? a : null
}

/** The same rule as a SQL expression on `persons`, for a where clause: NULL when the teacher has none. */
export const teacherClassroomAddressSql = (domain: string) => sql<string | null>`coalesce(
  case when lower(btrim(${persons.email})) like ${'%@' + domain.trim().toLowerCase()} then lower(btrim(${persons.email})) end,
  nullif(btrim(lower(${persons.classroomEmail})), ''))`

/** Every address the tenant already holds — the roster half of chooseAddress's taken-set. */
export async function assignedTeacherClassroomAddresses(tenantId: string): Promise<Set<string>> {
  const domain = await workspaceDomain(tenantId)
  const rows = await db.select({ email: persons.email, classroomEmail: persons.classroomEmail }).from(persons)
    .where(and(eq(persons.tenantId, tenantId), isNotNull(teacherClassroomAddressSql(domain))))
  const out = new Set<string>()
  for (const r of rows) { const a = teacherClassroomAddress(r, domain); if (a) out.add(a) }
  return out
}

/** The school address of the person a signed-in address belongs to in this tenant, or null (a teacher's own
 *  account on their dashboard, and the files opened as it). */
export async function schoolAddressOfSignedIn(tenantId: string, signedInEmail: string): Promise<string | null> {
  const domain = await workspaceDomain(tenantId)
  const rows = await db.select({ email: persons.email, classroomEmail: persons.classroomEmail }).from(persons)
    .where(and(eq(persons.tenantId, tenantId), sql`lower(btrim(${persons.email})) = ${signedInEmail.trim().toLowerCase()}`, sql`${persons.deletedAt} is null`))
  for (const r of rows) { const a = teacherClassroomAddress(r, domain); if (a) return a }
  return null
}
